package demo.pharma.payment; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.math.*; import java.util.*; public interface SupplierPaymentRepository extends JpaRepository<SupplierPayment,UUID>{ @Query("select coalesce(sum(p.amount),0) from SupplierPayment p where p.purchaseInvoice.id=:invoiceId") BigDecimal totalPaid(@Param("invoiceId") UUID invoiceId); }
